Section Inner.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x28 x29 x30 x31 : word).
  Variables (m : fmem) (SPR : Z) (js : list byte) (pos n b : Z).
  Variable POST : machine_state -> Prop.
  (* [comment removed for export] *)
  Hypothesis B18 : le1 x18 = [Z_to_bv 8 b].
  Hypothesis B19 : le1 x19 = [Z_to_bv 8 b].
  Hypothesis B20 : le1 x20 = [Z_to_bv 8 b].
  Hypothesis B21 : le1 x21 = [Z_to_bv 8 b].
  Hypothesis B22 : le1 x22 = [Z_to_bv 8 b].
  Hypothesis B23 : le1 x23 = [Z_to_bv 8 b].
  Hypothesis B25 : le1 x25 = [Z_to_bv 8 b].
  Hypothesis B28 : le1 x28 = [Z_to_bv 8 b].
  Hypothesis HN : x24 = Z_to_bv 64 n.
  Hypothesis HSPR : 0 < SPR /\ SPR + zlen js <= 2^64.
  Hypothesis HPOS : 0 <= pos.

  Notation ST pc mm x26 x27 :=
    (MS (mkR ra sp gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27
             x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma sp_inner : forall f spr i r m1,
    spread_inner f spr pos i n b = Ok r ->
    8 <= i < n -> n < 2^31 -> length js = length spr ->
    u8arr psegs m1 SPR (omerge js spr) ->
