Section Outer.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x5 x10 x12 x13 x14 x15 x16 x29 : word).
  Variables (m : fmem) (NC SPR : Z) (nc : list Z) (M1 : Z) (js : list byte).
  Variable POST : machine_state -> Prop.
  Hypothesis HM1 : 1 <= M1 <= 256.
  Hypothesis HNCL : M1 <= zlen nc.
  Hypothesis HNCR : Forall (fun c => - 32768 <= c < 32768) nc.
  Hypothesis HNC : 0 < NC /\ NC + 2 * zlen nc <= 2^64.
  Hypothesis HSPR : 0 < SPR /\ SPR + zlen js <= 2^64.
  Hypothesis DNS : NC + 2 * zlen nc <= SPR \/ SPR + zlen js <= NC.
  Hypothesis NCB0 : bytes_at psegs m NC (u16s (map (Z_to_bv 64) nc)).     (* [comment removed for export] *)

  Definition sp_inv (m1 : fmem) (spr : list (option Z)) : Prop :=
    u8arr psegs m1 SPR (omerge js spr) /\ munch [(SPR, SPR + zlen js)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1.

  Notation ST pc mm x6 x7 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 :=
    (MS (mkR ra sp gp tp x5 x6 x7 (Z_to_bv 64 SVK) (Z_to_bv 64 9) x10 (Z_to_bv 64 NC) x12 x13 x14 x15 x16 (Z_to_bv 64 SPR)
             x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 (Z_to_bv 64 M1) (Z_to_bv 64 (SPR + 8)))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma sp_outer : forall f s spr pos r m1 (x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 : word),
    spread_loop nc f s spr pos = Ok r ->
    Z.of_nat f = M1 - s -> 0 <= s < M1 -> 0 <= pos < 2^64 -> length spr = length js ->
    sp_inv m1 spr ->
    (forall m2 (y6 y7 y18 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 : word), sp_inv m2 r -> length r = length js ->
       evt psegs POST (ST 0x1bae0 m2 y6 y7 y18 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28)) ->
    evt psegs POST (ST 0x1b9f4 m1 (Z_to_bv 64 s) (Z_to_bv 64 pos) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27
                       (Z_to_bv 64 (s * SVK))).
Proof.
